package com.yeyamo_mobile.api.culture_service.domain;
import static com.yeyamo_mobile.api.culture_service.domain.CultureEnums.*;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="language_lessons") public class LanguageLesson{@Id private UUID id;@Column(name="language_code",nullable=false)private String languageCode;@Column(name="topic_id",nullable=false)private UUID topicId;@Column(nullable=false)private String title;private String description;@Column(nullable=false)private int difficulty;@Column(name="estimated_minutes",nullable=false)private int estimatedMinutes;@Enumerated(EnumType.STRING)@Column(nullable=false)private LessonStatus status;@Column(name="display_order",nullable=false)private int displayOrder;@Column(name="created_at",nullable=false)private Instant createdAt;protected LanguageLesson(){}public UUID getId(){return id;}public String getLanguageCode(){return languageCode;}public UUID getTopicId(){return topicId;}public String getTitle(){return title;}public String getDescription(){return description;}public int getDifficulty(){return difficulty;}public int getEstimatedMinutes(){return estimatedMinutes;}public LessonStatus getStatus(){return status;}public int getDisplayOrder(){return displayOrder;}}
